for x in select value from jsonb_array_elements('[{"identity":"repo:https://github.com/jianchang512/pyvideotrans","slug":"pyvideotrans-a2fd8602","name":"pyVideoTrans","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Dịch một video không chỉ là đổi câu chữ: còn phải khớp giọng, vai nói và thời lượng.","description":"pyVideoTrans kết nối nhận dạng lời nói, dịch phụ đề, lồng tiếng nhiều vai và ghép lại video. Điểm thực dụng là có thể dừng ở từng giai đoạn để sửa, thay vì nhận một thành phẩm tự động rồi không biết lỗi nằm ở đâu.","long_description":"ĐIỂM NỔI BẬT\n• Chuyển audio/video theo lô thành phụ đề SRT, có phân biệt người nói.\n• Gán voice cho từng vai; kết nối nhiều mô hình chạy local hoặc API.\n• GUI, CLI và WebUI; có công cụ tách giọng, ghép phụ đề và căn audio/video.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nDịch video hướng dẫn do bạn sở hữu sang tiếng Việt: sửa thuật ngữ ở phụ đề trước, chọn giọng sau và kiểm tra khớp thời gian ở bản xuất.\n\nBẮT ĐẦU\nWindows có gói chạy sẵn; macOS/Linux cần môi trường Python, FFmpeg và cấu hình provider theo tài liệu.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nKhông phải mọi engine đều hỗ trợ tiếng Việt như nhau. API có thể tính phí; clone giọng cần sự đồng ý và phải nghe lại tên riêng, tốc độ nói.","canonical_url":"https://github.com/jianchang512/pyvideotrans","repository_url":"https://github.com/jianchang512/pyvideotrans","documentation_url":"https://raw.githubusercontent.com/jianchang512/pyvideotrans/main/README.md","owner_name":"jianchang512","license":"GPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":31,"categories":["video","audio"],"primaryCategory":"video","selectionReason":"Phù hợp Video & Phụ đề: Dịch một video không chỉ là đổi câu chữ: còn phải khớp giọng, vai nói và thời lượng. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Dịch một video không chỉ là đổi câu chữ: còn phải khớp giọng, vai nói và thời lượng.","highlights":["Chuyển audio/video theo lô thành phụ đề SRT, có phân biệt người nói.","Gán voice cho từng vai; kết nối nhiều mô hình chạy local hoặc API.","GUI, CLI và WebUI; có công cụ tách giọng, ghép phụ đề và căn audio/video."],"example":"Dịch video hướng dẫn do bạn sở hữu sang tiếng Việt: sửa thuật ngữ ở phụ đề trước, chọn giọng sau và kiểm tra khớp thời gian ở bản xuất.","setup":"Windows có gói chạy sẵn; macOS/Linux cần môi trường Python, FFmpeg và cấu hình provider theo tài liệu.","limitations":"Không phải mọi engine đều hỗ trợ tiếng Việt như nhau. API có thể tính phí; clone giọng cần sự đồng ý và phải nghe lại tên riêng, tốc độ nói.","github":{"stars":18880,"forks":2334,"observedAt":"2026-09-03T16:08:22.123Z","url":"https://github.com/jianchang512/pyvideotrans","pushedAt":"2026-09-03T13:45:52Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/jianchang512/pyvideotrans/main/README.md","observedAt":"2026-09-03T16:10:00.050Z","sha256":"c2821199f779fe3644f3d6528a1bc724c0252ae4a4eda38a866c6e7ef4abca62"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"jianchang512/pyvideotrans:metadata","source_url":"https://github.com/jianchang512/pyvideotrans","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3AKDE%2Fkdenlive%20repo%3ASubtitleEdit%2Fsubtitleedit%20repo%3Ajianchang512%2Fpyvideotrans%20repo%3Akrillinai%2FKrillinAI%20repo%3AHuanshere%2FVideoLingo%20repo%3AChenyme%2FChenyme-AAVT%20repo%3Ayt-dlp%2Fyt-dlp%20repo%3AZulko%2Fmoviepy&per_page=100","stars":18880,"forks":2334,"license":"GPL-3.0"},"fetched_at":"2026-09-03T16:08:22.123Z"},{"source_type":"github","source_identifier":"jianchang512/pyvideotrans:readme:c2821199f779fe3644f3d6528a1bc724c0252ae4a4eda38a866c6e7ef4abca62","source_url":"https://raw.githubusercontent.com/jianchang512/pyvideotrans/main/README.md","raw_metadata":{"sha256":"c2821199f779fe3644f3d6528a1bc724c0252ae4a4eda38a866c6e7ef4abca62","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:00.050Z"}],"expected":null},{"identity":"repo:https://github.com/huanshere/videolingo","slug":"videolingo-80ea22be","name":"VideoLingo","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Phụ đề dễ đọc cần đúng nhịp và thuật ngữ, không chỉ một bản dịch sát từng từ.","description":"VideoLingo tập trung bản địa hóa video với nhận dạng mức từ, chia câu, bảng thuật ngữ và vòng dịch–phản tư–điều chỉnh. Tác giả hướng tới phụ đề một dòng và có thêm lồng tiếng. Đây là quy trình có bước kiểm soát chất lượng, không phải chứng nhận phụ đề đạt chuẩn Netflix.","long_description":"ĐIỂM NỔI BẬT\n• Dùng WhisperX và xử lý ngôn ngữ để chia, căn phụ đề.\n• Có thuật ngữ tùy chỉnh và bước xem lại bản dịch.\n• Tích hợp nhiều TTS; giao diện Streamlit có tạm dừng, tiếp tục và log tiến trình.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nLàm bản tiếng Việt của một bài hướng dẫn được cấp quyền, thống nhất tên công cụ rồi kiểm tra phụ đề trên màn hình điện thoại.\n\nBẮT ĐẦU\nTheo hướng dẫn uv hiện tại, chuẩn bị FFmpeg và cấu hình mô hình dịch/TTS.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nREADME chưa liệt kê tiếng Việt trong nhóm ngôn ngữ đầu vào được mô tả. Nhạc nền, số và ký tự đặc biệt có thể làm lệch timestamp; chất lượng lồng tiếng phụ thuộc provider.","canonical_url":"https://github.com/Huanshere/VideoLingo","repository_url":"https://github.com/Huanshere/VideoLingo","documentation_url":"https://raw.githubusercontent.com/Huanshere/VideoLingo/main/README.md","owner_name":"Huanshere","license":"Apache-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":32,"categories":["video","audio","content"],"primaryCategory":"video","selectionReason":"Phù hợp Video & Phụ đề: Phụ đề dễ đọc cần đúng nhịp và thuật ngữ, không chỉ một bản dịch sát từng từ. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Phụ đề dễ đọc cần đúng nhịp và thuật ngữ, không chỉ một bản dịch sát từng từ.","highlights":["Dùng WhisperX và xử lý ngôn ngữ để chia, căn phụ đề.","Có thuật ngữ tùy chỉnh và bước xem lại bản dịch.","Tích hợp nhiều TTS; giao diện Streamlit có tạm dừng, tiếp tục và log tiến trình."],"example":"Làm bản tiếng Việt của một bài hướng dẫn được cấp quyền, thống nhất tên công cụ rồi kiểm tra phụ đề trên màn hình điện thoại.","setup":"Theo hướng dẫn uv hiện tại, chuẩn bị FFmpeg và cấu hình mô hình dịch/TTS.","limitations":"README chưa liệt kê tiếng Việt trong nhóm ngôn ngữ đầu vào được mô tả. Nhạc nền, số và ký tự đặc biệt có thể làm lệch timestamp; chất lượng lồng tiếng phụ thuộc provider.","github":{"stars":18349,"forks":2018,"observedAt":"2026-09-03T16:08:22.123Z","url":"https://github.com/Huanshere/VideoLingo","pushedAt":"2026-08-23T15:23:27Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/Huanshere/VideoLingo/main/README.md","observedAt":"2026-09-03T16:10:00.806Z","sha256":"16f9d73cbeea9f29632c0ba7f9303f7175cdd6895249e2b287ba04fc3a912310"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"Huanshere/VideoLingo:metadata","source_url":"https://github.com/Huanshere/VideoLingo","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3AKDE%2Fkdenlive%20repo%3ASubtitleEdit%2Fsubtitleedit%20repo%3Ajianchang512%2Fpyvideotrans%20repo%3Akrillinai%2FKrillinAI%20repo%3AHuanshere%2FVideoLingo%20repo%3AChenyme%2FChenyme-AAVT%20repo%3Ayt-dlp%2Fyt-dlp%20repo%3AZulko%2Fmoviepy&per_page=100","stars":18349,"forks":2018,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:08:22.123Z"},{"source_type":"github","source_identifier":"Huanshere/VideoLingo:readme:16f9d73cbeea9f29632c0ba7f9303f7175cdd6895249e2b287ba04fc3a912310","source_url":"https://raw.githubusercontent.com/Huanshere/VideoLingo/main/README.md","raw_metadata":{"sha256":"16f9d73cbeea9f29632c0ba7f9303f7175cdd6895249e2b287ba04fc3a912310","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:00.806Z"}],"expected":null},{"identity":"repo:https://github.com/wan-video/wan2.2","slug":"wan-2-2-536738c4","name":"Wan 2.2","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Biến một ý tưởng hoặc ảnh chủ đạo thành cảnh chuyển động để đưa vào bản dựng.","description":"Wan 2.2 là bộ mô hình video có các nhánh tạo từ chữ, từ ảnh, từ giọng nói và animation nhân vật. Creator có thể dùng nó tạo từng cảnh rồi ghép bằng editor, thay vì kỳ vọng một prompt sẽ xuất ngay video dài hoàn chỉnh có phụ đề và nhịp kể.","long_description":"ĐIỂM NỔI BẬT\n• Có T2V, I2V và bản TI2V-5B hỗ trợ cả chữ lẫn ảnh.\n• README công bố đầu ra 720p/24fps cho bản 5B và tích hợp ComfyUI.\n• Các nhánh S2V/Animate phục vụ audio-driven video và chuyển động nhân vật.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nTạo một cảnh mở đầu từ ảnh chủ đạo đã duyệt, lựa chọn kết quả tốt rồi dựng cùng voice và phụ đề riêng.\n\nBẮT ĐẦU\nChọn đúng model và workflow chính chủ; so yêu cầu bộ nhớ trước khi tải trọng số hoặc thuê GPU.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nKhông bảo đảm nhân vật nhất quán hay chữ trong hình chính xác. Các nhánh có yêu cầu khác nhau; thông số tác giả không phải benchmark trên máy người dùng.","canonical_url":"https://github.com/Wan-Video/Wan2.2","repository_url":"https://github.com/Wan-Video/Wan2.2","documentation_url":"https://raw.githubusercontent.com/Wan-Video/Wan2.2/main/README.md","owner_name":"Wan-Video","license":"Apache-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":33,"categories":["video","image"],"primaryCategory":"video","selectionReason":"Phù hợp Video & Phụ đề: Biến một ý tưởng hoặc ảnh chủ đạo thành cảnh chuyển động để đưa vào bản dựng. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Biến một ý tưởng hoặc ảnh chủ đạo thành cảnh chuyển động để đưa vào bản dựng.","highlights":["Có T2V, I2V và bản TI2V-5B hỗ trợ cả chữ lẫn ảnh.","README công bố đầu ra 720p/24fps cho bản 5B và tích hợp ComfyUI.","Các nhánh S2V/Animate phục vụ audio-driven video và chuyển động nhân vật."],"example":"Tạo một cảnh mở đầu từ ảnh chủ đạo đã duyệt, lựa chọn kết quả tốt rồi dựng cùng voice và phụ đề riêng.","setup":"Chọn đúng model và workflow chính chủ; so yêu cầu bộ nhớ trước khi tải trọng số hoặc thuê GPU.","limitations":"Không bảo đảm nhân vật nhất quán hay chữ trong hình chính xác. Các nhánh có yêu cầu khác nhau; thông số tác giả không phải benchmark trên máy người dùng.","github":{"stars":17389,"forks":2224,"observedAt":"2026-09-03T16:08:28.626Z","url":"https://github.com/Wan-Video/Wan2.2","pushedAt":"2026-03-17T10:48:41Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/Wan-Video/Wan2.2/main/README.md","observedAt":"2026-09-03T16:10:06.016Z","sha256":"c04923dc9c509fe56b7f08a958b815dc62eb741a3969ad9d7a7586460b504ab5"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"Wan-Video/Wan2.2:metadata","source_url":"https://github.com/Wan-Video/Wan2.2","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3ALightricks%2FLTX-Video%20repo%3ALightricks%2FLTX-2%20repo%3AWan-Video%2FWan2.2%20repo%3ATencent-Hunyuan%2FHunyuanVideo%20repo%3AKwaiVGI%2FLivePortrait%20repo%3Alipku%2FLiveTalking%20repo%3AOpenTalker%2FSadTalker%20repo%3Afacefusion%2Ffacefusion&per_page=100","stars":17389,"forks":2224,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:08:28.626Z"},{"source_type":"github","source_identifier":"Wan-Video/Wan2.2:readme:c04923dc9c509fe56b7f08a958b815dc62eb741a3969ad9d7a7586460b504ab5","source_url":"https://raw.githubusercontent.com/Wan-Video/Wan2.2/main/README.md","raw_metadata":{"sha256":"c04923dc9c509fe56b7f08a958b815dc62eb741a3969ad9d7a7586460b504ab5","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:06.016Z"}],"expected":null},{"identity":"repo:https://github.com/mltframework/shotcut","slug":"shotcut-4546d98a","name":"Shotcut","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Ghép voice, hình và phụ đề thành video bằng một editor desktop mở.","description":"Shotcut là trình dựng video đa nền tảng. Nó phù hợp creator muốn tự chỉnh timeline và xuất thành phẩm mà không xây một ứng dụng bằng code.","long_description":"ĐIỂM NỔI BẬT\n• Dựng nhiều track, trộn nguồn có độ phân giải và tốc độ khung hình khác nhau.\n• Chỉnh âm thanh, transition và hiệu ứng theo keyframe.\n• Nhập, sửa, xuất hoặc gắn phụ đề vào video; có proxy hỗ trợ dựng.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nGhép các cảnh đã tạo với lời đọc, thêm phụ đề và chỉnh âm lượng trước khi xuất clip.\n\nBẮT ĐẦU\nTải bản phát hành chính chủ thay vì tự biên dịch; thử một project ngắn trước.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCần học timeline; máy và codec ảnh hưởng độ mượt. Không tự viết kịch bản hay bảo đảm media hợp pháp.","canonical_url":"https://github.com/mltframework/shotcut","repository_url":"https://github.com/mltframework/shotcut","documentation_url":"https://raw.githubusercontent.com/mltframework/shotcut/master/README.md","owner_name":"mltframework","license":"GPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":34,"categories":["video"],"primaryCategory":"video","selectionReason":"Phù hợp Video & Phụ đề: Ghép voice, hình và phụ đề thành video bằng một editor desktop mở. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Ghép voice, hình và phụ đề thành video bằng một editor desktop mở.","highlights":["Dựng nhiều track, trộn nguồn có độ phân giải và tốc độ khung hình khác nhau.","Chỉnh âm thanh, transition và hiệu ứng theo keyframe.","Nhập, sửa, xuất hoặc gắn phụ đề vào video; có proxy hỗ trợ dựng."],"example":"Ghép các cảnh đã tạo với lời đọc, thêm phụ đề và chỉnh âm lượng trước khi xuất clip.","setup":"Tải bản phát hành chính chủ thay vì tự biên dịch; thử một project ngắn trước.","limitations":"Cần học timeline; máy và codec ảnh hưởng độ mượt. Không tự viết kịch bản hay bảo đảm media hợp pháp.","github":{"stars":15067,"forks":1486,"observedAt":"2026-09-03T16:08:15.622Z","url":"https://github.com/mltframework/shotcut","pushedAt":"2026-09-03T04:48:03Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/mltframework/shotcut/master/README.md","observedAt":"2026-09-03T16:09:57.008Z","sha256":"2a38840fc2fafa928b9b8cfa4082581b1a1a699b920e5b9168a23c62bd6a9df8"},"trending":null,"extraSources":["https://www.shotcut.org/features/"]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"mltframework/shotcut:metadata","source_url":"https://github.com/mltframework/shotcut","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3AFujiwaraChoki%2FMoneyPrinterV2%20repo%3ARayVentura%2FShortGPT%20repo%3AOpenCut-app%2FOpenCut%20repo%3Amifi%2Flossless-cut%20repo%3AHandBrake%2FHandBrake%20repo%3Aobsproject%2Fobs-studio%20repo%3Amltframework%2Fshotcut%20repo%3AOpenShot%2Fopenshot-qt&per_page=100","stars":15067,"forks":1486,"license":"GPL-3.0"},"fetched_at":"2026-09-03T16:08:15.622Z"},{"source_type":"github","source_identifier":"mltframework/shotcut:readme:2a38840fc2fafa928b9b8cfa4082581b1a1a699b920e5b9168a23c62bd6a9df8","source_url":"https://raw.githubusercontent.com/mltframework/shotcut/master/README.md","raw_metadata":{"sha256":"2a38840fc2fafa928b9b8cfa4082581b1a1a699b920e5b9168a23c62bd6a9df8","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:57.008Z"},{"source_type":"manual","source_identifier":"https://www.shotcut.org/features/","source_url":"https://www.shotcut.org/features/","raw_metadata":{"relationship":"MAINTAINER","usage":"official_documentation"},"fetched_at":"2026-09-03T16:12:52.012Z"}],"expected":null},{"identity":"repo:https://github.com/zulko/moviepy","slug":"moviepy-1cde24ed","name":"MoviePy","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Biến những thao tác dựng lặp lại thành một công thức bằng Python.","description":"MoviePy là thư viện Python để cắt, nối, thêm chữ, ghép lớp và áp dụng hiệu ứng video. Nó hợp với creator có workflow theo mẫu và có người hoặc AI agent hỗ trợ code: dữ liệu thay đổi, công thức dựng được tái sử dụng.","long_description":"ĐIỂM NỔI BẬT\n• Cắt nối clip, phối lớp hình và tiêu đề.\n• Thao tác video và âm thanh trong cùng script.\n• Đọc/xuất các định dạng phổ biến và GIF trên nhiều hệ điều hành.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nTạo nhiều clip quote từ bảng nội dung, mỗi clip dùng cùng phông chữ, ảnh nền và nhạc đã được cấp quyền.\n\nBẮT ĐẦU\nChuẩn bị Python theo hướng dẫn bản hiện tại; dùng ví dụ dành cho MoviePy v2.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nv2 có thay đổi không tương thích với nhiều hướng dẫn v1. Không phải editor kéo thả; xử lý từng frame bằng Python có thể chậm với dự án nặng.","canonical_url":"https://github.com/Zulko/moviepy","repository_url":"https://github.com/Zulko/moviepy","documentation_url":"https://raw.githubusercontent.com/Zulko/moviepy/master/README.md","owner_name":"Zulko","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":35,"categories":["video","automation"],"primaryCategory":"video","selectionReason":"Phù hợp Video & Phụ đề: Biến những thao tác dựng lặp lại thành một công thức bằng Python. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Biến những thao tác dựng lặp lại thành một công thức bằng Python.","highlights":["Cắt nối clip, phối lớp hình và tiêu đề.","Thao tác video và âm thanh trong cùng script.","Đọc/xuất các định dạng phổ biến và GIF trên nhiều hệ điều hành."],"example":"Tạo nhiều clip quote từ bảng nội dung, mỗi clip dùng cùng phông chữ, ảnh nền và nhạc đã được cấp quyền.","setup":"Chuẩn bị Python theo hướng dẫn bản hiện tại; dùng ví dụ dành cho MoviePy v2.","limitations":"v2 có thay đổi không tương thích với nhiều hướng dẫn v1. Không phải editor kéo thả; xử lý từng frame bằng Python có thể chậm với dự án nặng.","github":{"stars":14878,"forks":2098,"observedAt":"2026-09-03T16:08:22.123Z","url":"https://github.com/Zulko/moviepy","pushedAt":"2026-08-26T06:17:08Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/Zulko/moviepy/master/README.md","observedAt":"2026-09-03T16:10:01.499Z","sha256":"34b932b6bb7320500bd1c1693ba615482f576672ea72a205eb017529cc714120"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"Zulko/moviepy:metadata","source_url":"https://github.com/Zulko/moviepy","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3AKDE%2Fkdenlive%20repo%3ASubtitleEdit%2Fsubtitleedit%20repo%3Ajianchang512%2Fpyvideotrans%20repo%3Akrillinai%2FKrillinAI%20repo%3AHuanshere%2FVideoLingo%20repo%3AChenyme%2FChenyme-AAVT%20repo%3Ayt-dlp%2Fyt-dlp%20repo%3AZulko%2Fmoviepy&per_page=100","stars":14878,"forks":2098,"license":"MIT"},"fetched_at":"2026-09-03T16:08:22.123Z"},{"source_type":"github","source_identifier":"Zulko/moviepy:readme:34b932b6bb7320500bd1c1693ba615482f576672ea72a205eb017529cc714120","source_url":"https://raw.githubusercontent.com/Zulko/moviepy/master/README.md","raw_metadata":{"sha256":"34b932b6bb7320500bd1c1693ba615482f576672ea72a205eb017529cc714120","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:01.499Z"}],"expected":null},{"identity":"repo:https://github.com/subtitleedit/subtitleedit","slug":"subtitle-edit-b24c146d","name":"Subtitle Edit","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"AI chép xong chưa có nghĩa phụ đề đã sẵn sàng đăng.","description":"Subtitle Edit cung cấp nơi chỉnh sửa và chuyển đổi phụ đề với video phát kèm. Khâu này rất cần cho creator tiếng Việt: rà tên riêng, sửa câu và xem lại bản phụ đề thay vì tin hoàn toàn đầu ra nhận dạng tự động. README hiện có hướng dẫn Windows, macOS và Linux.","long_description":"ĐIỂM NỔI BẬT\n• Chỉnh, chuyển đổi phụ đề và phát video trên thiết bị.\n• Tự lưu bản sao local; các chức năng cốt lõi hoạt động offline theo chính chủ.\n• Có lựa chọn dịch, nhận dạng, TTS hoặc OCR qua dịch vụ ngoài nếu người dùng bật.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nMở phụ đề đã tạo từ voice, nghe lại và sửa các câu khó đọc trước khi nhập vào phần mềm dựng.\n\nBẮT ĐẦU\nTải bản phù hợp từ Releases; kiểm tra yêu cầu hệ điều hành và phân biệt bản release candidate với bản ổn định.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nBật dịch vụ online sẽ gửi dữ liệu cần thiết tới provider đó. Tính riêng quyền riêng tư và phí của dịch vụ, không coi toàn bộ mọi tính năng là offline.","canonical_url":"https://github.com/SubtitleEdit/subtitleedit","repository_url":"https://github.com/SubtitleEdit/subtitleedit","documentation_url":"https://raw.githubusercontent.com/SubtitleEdit/subtitleedit/main/README.md","owner_name":"SubtitleEdit","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":36,"categories":["video","audio"],"primaryCategory":"video","selectionReason":"Phù hợp Video & Phụ đề: AI chép xong chưa có nghĩa phụ đề đã sẵn sàng đăng. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"AI chép xong chưa có nghĩa phụ đề đã sẵn sàng đăng.","highlights":["Chỉnh, chuyển đổi phụ đề và phát video trên thiết bị.","Tự lưu bản sao local; các chức năng cốt lõi hoạt động offline theo chính chủ.","Có lựa chọn dịch, nhận dạng, TTS hoặc OCR qua dịch vụ ngoài nếu người dùng bật."],"example":"Mở phụ đề đã tạo từ voice, nghe lại và sửa các câu khó đọc trước khi nhập vào phần mềm dựng.","setup":"Tải bản phù hợp từ Releases; kiểm tra yêu cầu hệ điều hành và phân biệt bản release candidate với bản ổn định.","limitations":"Bật dịch vụ online sẽ gửi dữ liệu cần thiết tới provider đó. Tính riêng quyền riêng tư và phí của dịch vụ, không coi toàn bộ mọi tính năng là offline.","github":{"stars":14044,"forks":1293,"observedAt":"2026-09-03T16:08:22.123Z","url":"https://github.com/SubtitleEdit/subtitleedit","pushedAt":"2026-09-03T15:47:35Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/SubtitleEdit/subtitleedit/main/README.md","observedAt":"2026-09-03T16:10:02.393Z","sha256":"e1cfe572ba631d19974c0ac4ff475d798871bee3ef15ac75757a050ce16abbd9"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"SubtitleEdit/subtitleedit:metadata","source_url":"https://github.com/SubtitleEdit/subtitleedit","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3AKDE%2Fkdenlive%20repo%3ASubtitleEdit%2Fsubtitleedit%20repo%3Ajianchang512%2Fpyvideotrans%20repo%3Akrillinai%2FKrillinAI%20repo%3AHuanshere%2FVideoLingo%20repo%3AChenyme%2FChenyme-AAVT%20repo%3Ayt-dlp%2Fyt-dlp%20repo%3AZulko%2Fmoviepy&per_page=100","stars":14044,"forks":1293,"license":"MIT"},"fetched_at":"2026-09-03T16:08:22.123Z"},{"source_type":"github","source_identifier":"SubtitleEdit/subtitleedit:readme:e1cfe572ba631d19974c0ac4ff475d798871bee3ef15ac75757a050ce16abbd9","source_url":"https://raw.githubusercontent.com/SubtitleEdit/subtitleedit/main/README.md","raw_metadata":{"sha256":"e1cfe572ba631d19974c0ac4ff475d798871bee3ef15ac75757a050ce16abbd9","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:02.393Z"}],"expected":null},{"identity":"repo:https://github.com/tencent-hunyuan/hunyuanvideo","slug":"hunyuanvideo-7102b58b","name":"HunyuanVideo","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Một mô hình video nền tảng đáng tham khảo, nhưng không phải lựa chọn nhẹ cho mọi laptop.","description":"Repo HunyuanVideo cung cấp mô hình, trọng số và mã suy luận video của Tencent. Nó có đường dùng qua Gradio, Diffusers và tích hợp cộng đồng. README cũng dẫn tới HunyuanVideo-1.5 mới hơn; không nên gộp thông số các phiên bản thành một lời hứa chung.","long_description":"ĐIỂM NỔI BẬT\n• Công khai code suy luận và trọng số của mô hình nền tảng.\n• Có hướng dẫn single-GPU, multi-GPU và trọng số FP8.\n• Có demo và các tích hợp ComfyUI được README dẫn nguồn.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nSo sánh phong cách cảnh tạo từ cùng một brief trước khi chọn model cho series video.\n\nBẮT ĐẦU\nĐọc mục Requirements đúng phiên bản; cấu hình gốc thử nghiệm trên Linux/NVIDIA cần bộ nhớ rất lớn.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nREADME bản gốc nêu khoảng 45–60GB GPU cho các cấu hình mẫu và khuyên 80GB. Bản lượng tử hóa/1.5 có điều kiện khác; không quảng cáo chạy ngay trên máy phổ thông.","canonical_url":"https://github.com/Tencent-Hunyuan/HunyuanVideo","repository_url":"https://github.com/Tencent-Hunyuan/HunyuanVideo","documentation_url":"https://raw.githubusercontent.com/Tencent-Hunyuan/HunyuanVideo/main/README.md","owner_name":"Tencent-Hunyuan","license":"Giấy phép Hunyuan riêng và điều kiện model; cần đọc trước khi dùng thương mại.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":37,"categories":["video"],"primaryCategory":"video","selectionReason":"Phù hợp Video & Phụ đề: Một mô hình video nền tảng đáng tham khảo, nhưng không phải lựa chọn nhẹ cho mọi laptop. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Một mô hình video nền tảng đáng tham khảo, nhưng không phải lựa chọn nhẹ cho mọi laptop.","highlights":["Công khai code suy luận và trọng số của mô hình nền tảng.","Có hướng dẫn single-GPU, multi-GPU và trọng số FP8.","Có demo và các tích hợp ComfyUI được README dẫn nguồn."],"example":"So sánh phong cách cảnh tạo từ cùng một brief trước khi chọn model cho series video.","setup":"Đọc mục Requirements đúng phiên bản; cấu hình gốc thử nghiệm trên Linux/NVIDIA cần bộ nhớ rất lớn.","limitations":"README bản gốc nêu khoảng 45–60GB GPU cho các cấu hình mẫu và khuyên 80GB. Bản lượng tử hóa/1.5 có điều kiện khác; không quảng cáo chạy ngay trên máy phổ thông.","github":{"stars":12496,"forks":1321,"observedAt":"2026-09-03T16:08:28.626Z","url":"https://github.com/Tencent-Hunyuan/HunyuanVideo","pushedAt":"2026-06-29T09:33:50Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/Tencent-Hunyuan/HunyuanVideo/main/README.md","observedAt":"2026-09-03T16:10:07.463Z","sha256":"fcc29022b5d80583e2f4b3b4f09145c4d65c4e7bf63bd4006ba367ea4d470427"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"Tencent-Hunyuan/HunyuanVideo:metadata","source_url":"https://github.com/Tencent-Hunyuan/HunyuanVideo","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3ALightricks%2FLTX-Video%20repo%3ALightricks%2FLTX-2%20repo%3AWan-Video%2FWan2.2%20repo%3ATencent-Hunyuan%2FHunyuanVideo%20repo%3AKwaiVGI%2FLivePortrait%20repo%3Alipku%2FLiveTalking%20repo%3AOpenTalker%2FSadTalker%20repo%3Afacefusion%2Ffacefusion&per_page=100","stars":12496,"forks":1321,"license":"NOASSERTION"},"fetched_at":"2026-09-03T16:08:28.626Z"},{"source_type":"github","source_identifier":"Tencent-Hunyuan/HunyuanVideo:readme:fcc29022b5d80583e2f4b3b4f09145c4d65c4e7bf63bd4006ba367ea4d470427","source_url":"https://raw.githubusercontent.com/Tencent-Hunyuan/HunyuanVideo/main/README.md","raw_metadata":{"sha256":"fcc29022b5d80583e2f4b3b4f09145c4d65c4e7bf63bd4006ba367ea4d470427","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:07.463Z"}],"expected":null},{"identity":"repo:https://github.com/krillinai/krillinai","slug":"krillinai-014f9394","name":"KrillinAI","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Từ video gốc đến bản dịch, voice và khung dọc trong một chuỗi có thể chia nhỏ.","description":"KrillinAI tổ chức pipeline bản địa hóa video cho người dùng và agent: nhận video, chép lời, dịch, lồng tiếng, đổi bố cục và tạo cover. Mỗi giai đoạn có thể gọi riêng qua CLI, thuận tiện ghép vào một video kit có bước duyệt.","long_description":"ĐIỂM NỔI BẬT\n• Nhận file local hoặc nguồn được phép; chia và dịch phụ đề bằng LLM.\n• Có thay thuật ngữ, lựa chọn TTS và bố cục ngang/dọc.\n• Desktop, server và CLI; tái sử dụng đầu ra giữa các giai đoạn.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nChuyển video demo của bạn sang bản dọc có phụ đề Việt, kiểm tra phần crop rồi mới làm cover và xuất.\n\nBẮT ĐẦU\nTải executable đúng hệ điều hành; chọn ASR phù hợp máy và cấu hình mô hình dịch/voice.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nDanh sách đầu vào trong README chưa xác nhận đầy đủ tiếng Việt. Không mặc định mọi video sẽ không lệch phụ đề như demo tác giả; clone giọng cần được phép.","canonical_url":"https://github.com/krillinai/KrillinAI","repository_url":"https://github.com/krillinai/KrillinAI","documentation_url":"https://raw.githubusercontent.com/krillinai/KrillinAI/master/README.md","owner_name":"krillinai","license":"GPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":38,"categories":["video","audio","social"],"primaryCategory":"video","selectionReason":"Phù hợp Video & Phụ đề: Từ video gốc đến bản dịch, voice và khung dọc trong một chuỗi có thể chia nhỏ. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Từ video gốc đến bản dịch, voice và khung dọc trong một chuỗi có thể chia nhỏ.","highlights":["Nhận file local hoặc nguồn được phép; chia và dịch phụ đề bằng LLM.","Có thay thuật ngữ, lựa chọn TTS và bố cục ngang/dọc.","Desktop, server và CLI; tái sử dụng đầu ra giữa các giai đoạn."],"example":"Chuyển video demo của bạn sang bản dọc có phụ đề Việt, kiểm tra phần crop rồi mới làm cover và xuất.","setup":"Tải executable đúng hệ điều hành; chọn ASR phù hợp máy và cấu hình mô hình dịch/voice.","limitations":"Danh sách đầu vào trong README chưa xác nhận đầy đủ tiếng Việt. Không mặc định mọi video sẽ không lệch phụ đề như demo tác giả; clone giọng cần được phép.","github":{"stars":11337,"forks":1086,"observedAt":"2026-09-03T16:08:22.123Z","url":"https://github.com/krillinai/KrillinAI","pushedAt":"2026-09-01T04:37:45Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/krillinai/KrillinAI/master/README.md","observedAt":"2026-09-03T16:10:02.992Z","sha256":"96dace816638f3111561a1c80685749cd4fa73b05c53721b15b4c51750603b87"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"krillinai/KrillinAI:metadata","source_url":"https://github.com/krillinai/KrillinAI","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3AKDE%2Fkdenlive%20repo%3ASubtitleEdit%2Fsubtitleedit%20repo%3Ajianchang512%2Fpyvideotrans%20repo%3Akrillinai%2FKrillinAI%20repo%3AHuanshere%2FVideoLingo%20repo%3AChenyme%2FChenyme-AAVT%20repo%3Ayt-dlp%2Fyt-dlp%20repo%3AZulko%2Fmoviepy&per_page=100","stars":11337,"forks":1086,"license":"GPL-3.0"},"fetched_at":"2026-09-03T16:08:22.123Z"},{"source_type":"github","source_identifier":"krillinai/KrillinAI:readme:96dace816638f3111561a1c80685749cd4fa73b05c53721b15b4c51750603b87","source_url":"https://raw.githubusercontent.com/krillinai/KrillinAI/master/README.md","raw_metadata":{"sha256":"96dace816638f3111561a1c80685749cd4fa73b05c53721b15b4c51750603b87","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:02.992Z"}],"expected":null},{"identity":"repo:https://github.com/lipku/livetalking","slug":"livetalking-feef1589","name":"LiveTalking","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Cho avatar nói theo văn bản hoặc audio, rồi dùng như một phần của workflow trình bày.","description":"LiveTalking ghép TTS với mô hình khẩu hình để tạo nhân vật số nói và truyền audio/video. Có thể kết nối LLM tùy chọn, nhưng không bắt buộc để làm video từ kịch bản đã duyệt. Nó là engine cần thiết lập, không phải người dẫn chương trình tự hiểu và chịu trách nhiệm nội dung.","long_description":"ĐIỂM NỔI BẬT\n• Hỗ trợ nhiều engine avatar, voice và nhân vật tùy chỉnh.\n• Đầu ra WebRTC, RTMP hoặc camera ảo; có điều khiển và ghi qua API.\n• Có ngắt lời, xử lý nhiều phiên và động tác khi không nói.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nDùng avatar được cấp quyền đọc phần giới thiệu khóa học từ kịch bản đã kiểm tra.\n\nBẮT ĐẦU\nTheo cấu hình GPU/Python chính chủ và thử trong mạng riêng trước khi triển khai server.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nClone mặt/giọng phải có sự đồng ý. README yêu cầu watermark/nhận diện LiveTalking cho video phát hành trên các nền tảng được nêu; kiểm tra thêm giấy phép model và bảo vệ API.","canonical_url":"https://github.com/lipku/LiveTalking","repository_url":"https://github.com/lipku/LiveTalking","documentation_url":"https://raw.githubusercontent.com/lipku/LiveTalking/main/README.md","owner_name":"lipku","license":"Apache-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":39,"categories":["video","audio","social"],"primaryCategory":"video","selectionReason":"Phù hợp Video & Phụ đề: Cho avatar nói theo văn bản hoặc audio, rồi dùng như một phần của workflow trình bày. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Cho avatar nói theo văn bản hoặc audio, rồi dùng như một phần của workflow trình bày.","highlights":["Hỗ trợ nhiều engine avatar, voice và nhân vật tùy chỉnh.","Đầu ra WebRTC, RTMP hoặc camera ảo; có điều khiển và ghi qua API.","Có ngắt lời, xử lý nhiều phiên và động tác khi không nói."],"example":"Dùng avatar được cấp quyền đọc phần giới thiệu khóa học từ kịch bản đã kiểm tra.","setup":"Theo cấu hình GPU/Python chính chủ và thử trong mạng riêng trước khi triển khai server.","limitations":"Clone mặt/giọng phải có sự đồng ý. README yêu cầu watermark/nhận diện LiveTalking cho video phát hành trên các nền tảng được nêu; kiểm tra thêm giấy phép model và bảo vệ API.","github":{"stars":9376,"forks":1487,"observedAt":"2026-09-03T16:08:28.626Z","url":"https://github.com/lipku/LiveTalking","pushedAt":"2026-08-30T00:52:02Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/lipku/LiveTalking/main/README.md","observedAt":"2026-09-03T16:10:10.015Z","sha256":"0230a38f572ba228f52d93248ca5381430455c4252730eb6a0815f9e8f690e12"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"lipku/LiveTalking:metadata","source_url":"https://github.com/lipku/LiveTalking","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3ALightricks%2FLTX-Video%20repo%3ALightricks%2FLTX-2%20repo%3AWan-Video%2FWan2.2%20repo%3ATencent-Hunyuan%2FHunyuanVideo%20repo%3AKwaiVGI%2FLivePortrait%20repo%3Alipku%2FLiveTalking%20repo%3AOpenTalker%2FSadTalker%20repo%3Afacefusion%2Ffacefusion&per_page=100","stars":9376,"forks":1487,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:08:28.626Z"},{"source_type":"github","source_identifier":"lipku/LiveTalking:readme:0230a38f572ba228f52d93248ca5381430455c4252730eb6a0815f9e8f690e12","source_url":"https://raw.githubusercontent.com/lipku/LiveTalking/main/README.md","raw_metadata":{"sha256":"0230a38f572ba228f52d93248ca5381430455c4252730eb6a0815f9e8f690e12","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:10.015Z"}],"expected":null},{"identity":"repo:https://github.com/lightricks/ltx-2","slug":"ltx-2-257daac7","name":"LTX-2","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Tạo hình chuyển động và âm thanh đồng bộ thay vì xử lý hai phần hoàn toàn tách rời.","description":"LTX-2 là họ mô hình audio-video của Lightricks; README hiện hướng dẫn trọng số LTX-2.5 và nhiều pipeline. Bản distilled là điểm khởi đầu nhanh hơn, còn DFR thêm bước chi tiết để ưu tiên chất lượng. Đây là nguồn tạo cảnh, chưa thay khâu biên tập thành phẩm.","long_description":"ĐIỂM NỔI BẬT\n• Sinh video có âm thanh đồng bộ trong cùng hệ mô hình.\n• Có đường text/image-to-video và lựa chọn pipeline theo tài nguyên.\n• Tài liệu chỉ rõ offload, lượng tử hóa và phần tải model bổ sung.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nThử cảnh sản phẩm ngắn với chuyển động và âm thanh môi trường, rồi ghép voice thương hiệu và phụ đề trong editor.\n\nBẮT ĐẦU\nĐọc Quick Start đúng phiên bản và chấp nhận điều khoản model nếu nguồn tải yêu cầu.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nBộ tải mẫu hiện khoảng 66GiB, không phải ứng dụng tải nhẹ. DFR chậm và tốn VRAM hơn; quyền code, model và dịch vụ API phải kiểm tra riêng.","canonical_url":"https://github.com/Lightricks/LTX-2","repository_url":"https://github.com/Lightricks/LTX-2","documentation_url":"https://raw.githubusercontent.com/Lightricks/LTX-2/main/README.md","owner_name":"Lightricks","license":"Đọc LICENSE và điều khoản model LTX được chọn; không coi open access là miễn phí thương mại vô điều kiện.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":40,"categories":["video","audio"],"primaryCategory":"video","selectionReason":"Phù hợp Video & Phụ đề: Tạo hình chuyển động và âm thanh đồng bộ thay vì xử lý hai phần hoàn toàn tách rời. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Tạo hình chuyển động và âm thanh đồng bộ thay vì xử lý hai phần hoàn toàn tách rời.","highlights":["Sinh video có âm thanh đồng bộ trong cùng hệ mô hình.","Có đường text/image-to-video và lựa chọn pipeline theo tài nguyên.","Tài liệu chỉ rõ offload, lượng tử hóa và phần tải model bổ sung."],"example":"Thử cảnh sản phẩm ngắn với chuyển động và âm thanh môi trường, rồi ghép voice thương hiệu và phụ đề trong editor.","setup":"Đọc Quick Start đúng phiên bản và chấp nhận điều khoản model nếu nguồn tải yêu cầu.","limitations":"Bộ tải mẫu hiện khoảng 66GiB, không phải ứng dụng tải nhẹ. DFR chậm và tốn VRAM hơn; quyền code, model và dịch vụ API phải kiểm tra riêng.","github":{"stars":9339,"forks":1471,"observedAt":"2026-09-03T16:08:28.626Z","url":"https://github.com/Lightricks/LTX-2","pushedAt":"2026-08-26T10:47:10Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/Lightricks/LTX-2/main/README.md","observedAt":"2026-09-03T16:10:10.535Z","sha256":"9c58c07e95872d9b810da302518e72795c3aec8d26256b7241438a204504f821"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"Lightricks/LTX-2:metadata","source_url":"https://github.com/Lightricks/LTX-2","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3ALightricks%2FLTX-Video%20repo%3ALightricks%2FLTX-2%20repo%3AWan-Video%2FWan2.2%20repo%3ATencent-Hunyuan%2FHunyuanVideo%20repo%3AKwaiVGI%2FLivePortrait%20repo%3Alipku%2FLiveTalking%20repo%3AOpenTalker%2FSadTalker%20repo%3Afacefusion%2Ffacefusion&per_page=100","stars":9339,"forks":1471,"license":"NOASSERTION"},"fetched_at":"2026-09-03T16:08:28.626Z"},{"source_type":"github","source_identifier":"Lightricks/LTX-2:readme:9c58c07e95872d9b810da302518e72795c3aec8d26256b7241438a204504f821","source_url":"https://raw.githubusercontent.com/Lightricks/LTX-2/main/README.md","raw_metadata":{"sha256":"9c58c07e95872d9b810da302518e72795c3aec8d26256b7241438a204504f821","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:10.535Z"}],"expected":null}]'::jsonb) loop
